    ox, oy = observation["opponent_position"]
    w, h = observation["grid_width"], observation["grid_height"]
    resources = observation.get("resources") or []
    obstacles = observation.get("obstacles") or []
    if not resources:
        return [0, 0]

    obs = set()
    for p in obstacles:
        if isinstance(p, (list, tuple)) and len(p) == 2:
            obs.add((p[0], p[1]))

    def in_bounds(x, y):
        return 0 <= x < w and 0 <= y < h

    def cheb(x1, y1, x2, y2):
        dx = x1 - x2
        if dx < 0:
            dx = -dx
        dy = y1 - y2
        if dy < 0:
            dy = -dy
        return dx if dx > dy else dy

    def obstacle_penalty(x, y):
        pen = 0
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if (x + dx, y + dy) in obs:
                    pen += 3
        return pen

    opp_factor = 1.2
    tr = observation.get("turns_remaining", 0)
    rem = observation.get("remaining_resource_count", len(resources))
    aggress = 1 if rem <= 6 else 0
    time_bias = 0 if tr <= 0 else (1 if tr <= 8 else 0)

    best = None
    best_score = None
    for rx, ry in resources:
        if (rx, ry) in obs:
            continue
        sd = cheb(sx, sy, rx, ry)
        od = cheb(ox, oy, rx, ry)
        # Prefer targets we can reach first; also account for proximity to obstacles.
        s = (sd - opp_factor * od) + obstacle_penalty(rx, ry)
        if od < sd:
            s += 8 + (aggress * 4)
        if time_bias:
            s += sd // 2
        key = (s, sd, rx, ry)
        if best is None or key < best_score:
            best = (rx, ry)
            best_score = key

    tx, ty = best
    dx = 0 if tx == sx else (1 if tx > sx else -1)
    dy = 0 if ty == sy else (1 if ty > sy else -1)

    candidates = []
    for mdx in (dx, 0, -dx):
        for mdy in (dy, 0, -dy):
            if mdx == 0 and mdy == 0:
                continue
            nx, ny = sx + mdx, sy + mdy
            if not in_bounds(nx, ny):
                continue
            candidates.append((mdx, mdy))

    if not candidates:
        candidates = [(dx, dy), (0, 0)]

    def move_score(mdx, mdy):
        nx, ny = sx + mdx, sy + mdy
        if (nx, ny) in obs:
            return 10**9
        # Primary: reduce distance to target; Secondary: avoid obstacles; Tertiary: avoid opponent getting closer.
        d = cheb(nx, ny, tx, ty)
        oppd = cheb(ox, oy, tx, ty)
        return d + obstacle_penalty(nx, ny) - 0.3 * oppd

    best_m = None
    best_ms = None
    for mdx, mdy in candidates + [(0, 0)]:
        ns = move_score(mdx, mdy)
        if best_m is None or ns < best_ms:
            best_m = (mdx, mdy)
            best_ms = ns
    return [int(best_m[0]), int(best_m[1])]

